                    if abs(E[1] - S[1]) > 1e-9:
                        t = (hh - S[1]) / (E[1] - S[1])
                        ix = (S[0] + t*(E[0]-S[0]), S[1] + t*(E[1]-S[1]))
                        new_poly.append(ix)
                S = E
    poly = new_poly

    # Calculate area using Shoelace formula
    area = 0.0
    n = len(poly)
    if n < 3:
        print(f"{0.0:.9f}")
        return

    for i in range(n):
        x1, y1 = poly[i]
        x2, y2 = poly[(i + 1) % n]
        area += (x1 * y2 - x2 * y1)

    area = abs(area) / 2.0
    print(f"{area:.9f}")

if __name__ == "__main__":
    solve()
